"""Materials course: reviewed web notes organized by the supplied 15-chapter source.
Original PDFs retain every source problem and derivation. Web examples below are
explicitly labelled teaching examples, rather than attributed to exam papers.
"""
CHAPTERS=[]
def chapter(title,en,lede):
 c={'title':title,'en':en,'lede':lede,'sections':[],'examples':[]};CHAPTERS.append(c);return c
def sec(title,text,eqs,points,note='',fig=None):
 CHAPTERS[-1]['sections'].append(dict(title=title,text=text,eqs=eqs,points=points,note=note,fig=fig))
def ex(title,q,steps,eqs,answer):
 CHAPTERS[-1]['examples'].append(dict(title=title,q=q,steps=steps,eqs=eqs,answer=answer))

chapter('力的基本觀念','Fundamentals of Force','從力與力矩出發，建立自由體圖、平衡方程式與截面內力。這些工具是後續應力、扭轉與彎曲分析的起點。')
sec('力學的分類',['靜力學討論平衡，動力學討論運動與造成運動的力；材料力學進一步考慮構件的變形及其內部應力。','剛體模型適合求支承反力，變形體模型則能回答伸長、撓曲及強度問題。同一構件在不同分析步驟可以採取不同模型。'],[],['先辨認問題要求的是外力、內力、應力或位移。','先求整體平衡，再分析材料與截面。'],'平衡不代表沒有變形；外力平衡的拉桿仍然可以伸長。','models')
sec('力的重要性質',['力具有大小、方向及作用點。平面力可以沿兩個互相垂直的座標軸分解。','力對一點的力矩取決於作用線與該點的垂直距離；力偶的合力為零，但仍有旋轉效應。'],[(r'F_x=F\cos\theta,\quad F_y=F\sin\theta','角度從正向水平軸量起'),(r'\mathbf M_O=\mathbf r\times\mathbf F,\quad |M_O|=Fd','力臂須使用垂直距離')],['統一力與長度的單位，例如牛頓與公尺。','先約定逆時針力矩為正，再依同一慣例計算。'],'力的可傳性適用於剛體的外效應；移動作用點可能改變局部應力。','force')
sec('自由體圖',['把研究對象從周圍環境分離，將接觸與約束改以力或力矩表示，就是自由體圖。','滾支承通常提供一個法向反力，平面鉸支承提供兩個反力分量，固定端則另有反力矩。'],[],['標示所有外力、分布負載、尺寸及支承反力。','只畫作用在所選物體上的力，不把作用與反作用混在同一張圖。','對未知反力先假設方向；算出負值表示實際方向相反。'],'力矩必須附上參考點；距離標示應放在構件外側。','supports')
sec('平面力系之合成及平衡',['平面剛體平衡需要兩個方向的合力及繞任一點的合力矩同時為零。','分布負載可以用其負載圖的面積換算合力，作用點位於該面積的形心。'],[(r'\sum F_x=0,\quad\sum F_y=0,\quad\sum M_O=0','三個獨立的平面平衡方程式'),(r'R=\int_a^b w(x)\,dx,\quad \bar x=\frac{\int_a^b xw(x)\,dx}{R}','非零合力的作用位置')],['取矩點選在未知反力交點，常可減少未知數。','三角形負載合力位於較大端起算的三分之一底長處。'],'整體平衡可求反力，但通常無法單獨決定靜不定系統的所有未知量。','distributed')
sec('內力分析',['在欲求內力的位置假想切開構件，取其中一側作自由體圖。平面桿件截面內力可分成軸力、剪力與彎矩。','以切開後的局部平衡求內力，並在負載改變的位置分段。'],[(r'\sum F_{\parallel}=0,\quad\sum F_{\perp}=0,\quad\sum M_{\mathrm{cut}}=0','分別求軸力、剪力與彎矩')],['軸力沿構件軸線，剪力沿截面切線，彎矩使構件彎曲。','切面兩側的內力大小相等、方向相反。'],'本課程拉力為正；剪力與彎矩依第九章的正號圖約定。','cut')
ex('簡支樑的支承反力','長6 m的簡支樑，在左支承右方2 m處受到12 kN向下集中力。求左右支承反力。',['取整根樑的自由體圖，先對左支承取矩。','求右反力後，再以鉛直方向平衡求左反力。'],[(r'R_B\times6-12\times2=0','力矩單位為千牛頓公尺'),(r'R_B=4\ \mathrm{kN},\quad R_A=12-4=8\ \mathrm{kN}','兩個反力均向上')],'左右反力之和等於12 kN，且力矩平衡。')
ex('截面軸力與平均應力','等截面直桿受20 kN拉力，截面面積為400 mm²。求截面軸力與平均正向應力。',['切開桿件一側，由平衡得到內部軸力等於外力。','將千牛頓換為牛頓，搭配平方毫米可直接得到MPa。'],[(r'N=20\ \mathrm{kN},\quad \sigma=\frac{20000}{400}=50\ \mathrm{MPa}','拉應力取正')],'截面內力為20 kN拉力，平均拉應力50 MPa。')

chapter('應力','Stress','將截面內力轉為單位面積上的應力，並以應力轉換、莫爾圓與應力張量描述不同方向的受力狀態。')
sec('正向應力與剪應力',['正向應力垂直於截面，剪應力平行於截面。以合力除以面積得到的是平均應力，不一定等於每一點的局部值。','安全係數用來比較材料強度與設計容許應力；選用降伏或極限強度，應依題意及破壞模式決定。'],[(r'\sigma_{\mathrm{avg}}=\frac{N}{A},\quad\tau_{\mathrm{avg}}=\frac{V}{A}','均勻或平均應力'),(r'n=\frac{\sigma_{\mathrm{strength}}}{\sigma_{\mathrm{allow}}}','強度與容許應力使用相同單位')],['雙剪接頭有兩個承受剪力的截面。','孔邊、尖角與負載作用處可能發生應力集中。'],'樑內剪應力通常不均勻，不能以平均剪應力取代最大值。','stress')
sec('平面應力',['薄板面內受力且表面無面外負載時，常可近似為平面應力。改變觀察截面，正向應力與剪應力都會改變。','主平面上的剪應力為零。莫爾圓把同一點的應力轉換畫成圓，實體轉角在圓上對應兩倍角度。'],[(r'\sigma_{x\prime}=\frac{\sigma_x+\sigma_y}{2}+\frac{\sigma_x-\sigma_y}{2}\cos2\theta+\tau_{xy}\sin2\theta','正角為座標軸逆時針旋轉'),(r'\tau_{x\prime y\prime}=-\frac{\sigma_x-\sigma_y}{2}\sin2\theta+\tau_{xy}\cos2\theta','採用正面沿正軸的剪應力慣例'),(r'C=\frac{\sigma_x+\sigma_y}{2},\quad R=\sqrt{\left(\frac{\sigma_x-\sigma_y}{2}\right)^2+\tau_{xy}^2}','莫爾圓圓心與半徑'),(r'\sigma_{1,2}=C\pm R,\quad\tau_{\max,\mathrm{in}}=R','平面內最大剪應力')],['求主方向時以兩參數反正切判斷象限。','求絕對最大剪應力時，還要把面外的零主應力列入排序。'],'平面應力不等於平面應變。','mohr')
sec('應力張量',['三維應力由三個正向應力與三組互等剪應力描述。沒有體偶力時，力矩平衡使應力張量對稱。','柯西公式把應力張量與截面單位法向量相乘，得到該截面的應力向量；再分解成法向與切向分量。'],[(r't_i=\sum_{j=1}^{3}\sigma_{ij}n_j,\quad\sigma_n=\mathbf n\cdot\mathbf t','對稱張量下的柯西應力公式'),(r'\tau_n=\sqrt{\mathbf t\cdot\mathbf t-\sigma_n^2}','截面上的剪應力大小'),(r'\det(\boldsymbol\sigma-\lambda\mathbf I)=0','主應力為應力張量的特徵值')],['先確認法向量長度為一。','三維最大剪應力等於最大、最小主應力差的一半。'],'張量分量的下標定義須前後一致；本課程使用對稱應力張量。','traction')
sec('應力場分析',['應力場是各應力分量隨空間位置的變化。對微小元素列平衡可得到應力的微分平衡方程。','要判斷一個應力場是否可能，除了內部平衡，也要檢查邊界上的應力向量是否等於指定面力。'],[(r'\frac{\partial\sigma_x}{\partial x}+\frac{\partial\tau_{xy}}{\partial y}+b_x=0','二維靜力平衡，體力為每單位體積的力'),(r'\frac{\partial\tau_{xy}}{\partial x}+\frac{\partial\sigma_y}{\partial y}+b_y=0','另一方向的微分平衡')],['代入各分量後，逐一計算偏微分。','若題目有自重，體力項不可省略。'],'平衡是必要條件；完整彈性解還須滿足組成律與相容條件。')
ex('主應力與最大剪應力','某點平面應力為水平80 MPa、鉛直20 MPa及正剪應力40 MPa。求主應力與絕對最大剪應力。',['先求莫爾圓圓心及半徑。','將零面外應力與兩個平面內主應力一起排序。'],[(r'C=50\ \mathrm{MPa},\quad R=\sqrt{30^2+40^2}=50\ \mathrm{MPa}',''),(r'\sigma_1=100,\quad\sigma_2=0,\quad\sigma_3=0\quad(\mathrm{MPa})','三維主應力排序'),(r'\tau_{\max,\mathrm{abs}}=\frac{100-0}{2}=50\ \mathrm{MPa}','')],'主應力為100、0、0 MPa；絕對最大剪應力50 MPa。')
ex('雙剪銷的平均剪應力','直徑10 mm的銷受到8 kN負載，接頭為雙剪。求每個剪面的平均剪應力。',['計算單一圓截面的面積。','總負載由兩個剪面共同承受。'],[(r'A=\frac{\pi10^2}{4}=78.54\ \mathrm{mm^2}',''),(r'\tau_{\mathrm{avg}}=\frac{8000}{2(78.54)}=50.93\ \mathrm{MPa}','')],'每個剪面的平均剪應力約50.9 MPa。')

chapter('應變分析','Strain','用長度與角度的改變量描述變形。掌握工程剪應變與張量剪應變的差別，再處理應變轉換、應變規與位移場。')
sec('正向應變與剪應變',['正向應變是長度改變量相對於原長的比值，拉伸為正、縮短為負。小變形時，工程剪應變是原來互相垂直的兩線段夾角的減少量。','應變沒有物理量綱。微應變表示百萬分之一；角度計算應採弧度。'],[(r'\varepsilon=\frac{L-L_0}{L_0}=\frac{\delta}{L_0}','工程正向應變'),(r'\gamma_{xy}\simeq\frac{\partial u}{\partial y}+\frac{\partial v}{\partial x}','小變形工程剪應變')],['變形量與原長使用相同長度單位。','剛體平移不產生應變；小角度剛體轉動也不產生對稱應變。'],'工程剪應變是張量剪應變的兩倍。','strain')
sec('平面應變',['應變轉換的形式與應力轉換相似，但剪應變須以工程剪應變的一半放入莫爾圓。','三片不同方向的應變規可用方向轉換公式反求面內應變，再求主應變。'],[(r'\varepsilon_{x\prime}=\frac{\varepsilon_x+\varepsilon_y}{2}+\frac{\varepsilon_x-\varepsilon_y}{2}\cos2\theta+\frac{\gamma_{xy}}2\sin2\theta','任意方向的正向應變'),(r'\varepsilon_{1,2}=\frac{\varepsilon_x+\varepsilon_y}{2}\pm\sqrt{\left(\frac{\varepsilon_x-\varepsilon_y}{2}\right)^2+\left(\frac{\gamma_{xy}}2\right)^2}','主應變'),(r'\gamma_{\max,\mathrm{in}}=\sqrt{(\varepsilon_x-\varepsilon_y)^2+\gamma_{xy}^2}','面內最大工程剪應變')],['應變莫爾圓的縱軸是工程剪應變的一半。','0°、45°、90°應變花可直接建立三個線性方程式。'],'平面應變指定面外應變為零，面外應力一般不為零。','rosette')
sec('應變張量',['位移場對位置的梯度可分成對稱的應變與反對稱的剛體轉動。應變張量的特徵值就是三個主應變。','不是任意給定的應變分布都能拼成連續變形；相容方程式確保位移單值且連續。'],[(r'\varepsilon_{ij}=\frac12\left(\frac{\partial u_i}{\partial x_j}+\frac{\partial u_j}{\partial x_i}\right)','小應變張量'),(r'\frac{\partial^2\varepsilon_x}{\partial y^2}+\frac{\partial^2\varepsilon_y}{\partial x^2}=\frac{\partial^2\gamma_{xy}}{\partial x\partial y}','二維小應變相容條件')],['先求位移的一階偏導數，再組成應變分量。','由應變回推位移時，積分常數可能代表剛體運動。'],'線性小應變公式不適合直接描述大轉動。')
ex('應變花反算','0°、45°、90°應變規讀值分別為400、300、−200微應變。求工程剪應變與主應變。',['0°與90°讀值分別給出兩個正向應變。','45°讀值等於兩正向應變平均值加上工程剪應變的一半。'],[(r'\gamma_{xy}=2(300)-400-(-200)=400\ \mu\varepsilon',''),(r'\varepsilon_{1,2}=100\pm\sqrt{300^2+200^2}','單位為微應變'),(r'\varepsilon_1=460.6\ \mu\varepsilon,\quad\varepsilon_2=-260.6\ \mu\varepsilon','')],'工程剪應變400微應變，主應變約460.6及−260.6微應變。')
ex('拉桿的長度改變','標距250 mm的試件伸長0.15 mm。求工程應變及微應變。',['以原始標距作分母。','將無因次應變乘上一百萬，換成微應變。'],[(r'\varepsilon=\frac{0.15}{250}=0.0006=600\ \mu\varepsilon','')],'工程應變0.0006，亦即600微應變。')

chapter('材料組成律','Constitutive Relations','由拉伸試驗認識材料的彈性、降伏與塑性，再以虎克定律連接應力與應變，為各類構件分析建立材料模型。')
sec('材料拉伸試驗',['工程應力使用原始截面積，工程應變使用原始標距；真應力與真應變則追蹤當下的尺寸變化。','應力應變圖的初始斜率為楊氏模數。降伏不明顯時，可用0.2%偏距線與曲線交點定義偏距降伏強度。'],[(r'\sigma=E\varepsilon,\quad\tau=G\gamma','線彈性區間的單軸與純剪關係'),(r'\sigma_{\mathrm{true}}=\frac{P}{A_{\mathrm{current}}},\quad\varepsilon_{\mathrm{true}}=\ln\frac L{L_0}','均勻變形時的真應力與真應變'),(r'u=\int_0^{\varepsilon}\sigma\,d\varepsilon','應變能密度為曲線下方的面積')],['彈性表示卸載後可恢復，不一定表示應力與應變線性。','頸縮以後，工程應力下降不代表局部真應力必定下降。'],'偏距線從應變0.002起畫，斜率與初始彈性段相同。','curve')
sec('材料非彈性軸向變形',['彈性完全塑性模型在降伏以前呈線性，之後在固定降伏應力下累積塑性應變。','卸載通常沿彈性模數的斜率返回；回到零應力仍保留的應變稱為永久應變。靜不定組合構件還可能留下自平衡的殘留應力。'],[(r'\varepsilon=\varepsilon_e+\varepsilon_p,\quad\varepsilon_e=\frac\sigma E','彈性與塑性應變分解')],['先算實際加載狀態，再以彈性卸載量相減。','殘留應力必須同時滿足平衡與變形相容。'],'單一自由拉桿卸載後可有永久應變，但不一定有殘留應力。','plastic')
sec('應力與應變轉換',['均質等向線彈性材料的正向應變受到三個方向的正向應力共同影響。泊松比反映單軸受力時的側向收縮。','楊氏模數、剪力模數、體積模數及泊松比不是四個獨立常數；等向線彈性材料只需要其中兩個。'],[(r'\varepsilon_x=\frac{\sigma_x-\nu(\sigma_y+\sigma_z)}{E}','其餘兩方向以循環換標得到'),(r'\gamma_{xy}=\frac{\tau_{xy}}G,\quad E=2G(1+\nu)','工程剪應變'),(r'K=\frac E{3(1-2\nu)},\quad\varepsilon_v=\varepsilon_x+\varepsilon_y+\varepsilon_z','體積模數與小體積應變'),(r'u=\frac12(\sigma_x\varepsilon_x+\sigma_y\varepsilon_y+\sigma_z\varepsilon_z+\tau_{xy}\gamma_{xy}+\tau_{yz}\gamma_{yz}+\tau_{zx}\gamma_{zx})','線彈性應變能密度')],['平面應力時面外應力為零，但泊松效應使面外應變通常不為零。','熱應變應另外加在機械應變上。'],'等向線彈性公式不可直接套用在一般各向異性複材。')
ex('泊松效應','鋼桿受100 MPa單軸拉應力，楊氏模數200 GPa，泊松比0.30。求軸向與側向應變。',['把200 GPa換成200000 MPa。','側向應變為軸向應變的負泊松比倍。'],[(r'\varepsilon_x=\frac{100}{200000}=500\ \mu\varepsilon',''),(r'\varepsilon_y=\varepsilon_z=-0.3(500)=-150\ \mu\varepsilon','')],'軸向伸長500微應變，兩個側向各收縮150微應變。')
ex('完全塑性材料卸載','某材料楊氏模數200 GPa，降伏應力250 MPa。加載至總應變0.003後完全卸載，求永久應變。',['卸載彈性回復量等於最大應力除以楊氏模數。','從總應變中減去彈性回復量。'],[(r'\varepsilon_e=\frac{250}{200000}=0.00125',''),(r'\varepsilon_p=0.003-0.00125=0.00175','')],'永久應變0.00175，亦即1750微應變。')

chapter('薄壁容器','Thin-Walled Pressure Vessels','從截開容器的自由體圖推導環向與軸向應力，分辨封閉圓筒與球殼，並用平面應力處理容器表面的變形及強度。')
sec('薄壁容器的應力分析',['壁厚遠小於半徑時，可以近似壁內的膜應力均勻分布。常見初步判斷為半徑與壁厚比至少約十，但端部與接頭附近仍須另行評估。','封閉圓筒沿縱向切半，由壓力投影面積與兩側壁力平衡，得到環向應力；沿橫截面切開則得到軸向應力。球殼因旋轉對稱，兩個切向主應力相等。'],[(r'\sigma_h=\frac{pr}{t},\quad\sigma_l=\frac{pr}{2t}','封閉薄壁圓筒；半徑採內半徑的薄壁近似'),(r'\sigma_{\mathrm{sphere}}=\frac{pr}{2t}','薄壁球形容器'),(r'\varepsilon_h=\frac{\sigma_h-\nu\sigma_l}{E},\quad\varepsilon_l=\frac{\sigma_l-\nu\sigma_h}{E}','忽略徑向應力的平面應力近似'),(r'\frac{\Delta V}{V}\simeq2\varepsilon_h+\varepsilon_l','圓筒容積的小變形近似')],['壓力應取內外壓力差。','圓筒環向應力是封閉端軸向應力的兩倍。','開口端且沒有端蓋傳力時，不可直接套用封閉端的軸向應力。'],'薄壁近似忽略的徑向應力在內表面實際為負內壓；厚壁容器須用厚壁理論。','pressure')
ex('封閉圓筒的應力與直徑改變','內壓2 MPa、內半徑250 mm、壁厚5 mm的封閉圓筒，楊氏模數200 GPa，泊松比0.30。求膜應力及直徑增加量。',['先由壓力與幾何量求兩個膜應力。','由廣義虎克定律求環向應變，再乘原直徑。'],[(r'\sigma_h=\frac{2(250)}5=100\ \mathrm{MPa},\quad\sigma_l=50\ \mathrm{MPa}',''),(r'\varepsilon_h=\frac{100-0.3(50)}{200000}=0.000425',''),(r'\Delta D=500(0.000425)=0.2125\ \mathrm{mm}','')],'環向100 MPa、軸向50 MPa；直徑增加0.2125 mm。')
ex('球殼所需壁厚','球形容器內半徑500 mm，設計內壓1.5 MPa，容許膜應力75 MPa。不計腐蝕裕量與接頭效率，求所需壁厚。',['球殼的兩個切向應力相同。','將容許應力代入球殼公式並反求壁厚。'],[(r't=\frac{pr}{2\sigma_{\mathrm{allow}}}=\frac{1.5(500)}{2(75)}=5\ \mathrm{mm}','')],'理想薄壁模型所需壁厚5 mm。')

chapter('桿構件之軸向負載','Axially Loaded Members','結合平衡、組成律與變形相容，求拉壓桿的位移、熱應力與靜不定反力，再以能量及維氏圖理解桿系變形。')
sec('軸向負載',['遠離負載作用區後，局部應力分布通常趨近簡化模型，這是聖維南原理的用途。桿的伸長量由各微段軸向應變沿長度累加而成。','靜定桿可先以平衡求內力；靜不定桿需要再加入固定端、接頭或剛板的變形相容條件。'],[(r'\delta=\int_0^L\frac{N(x)}{A(x)E(x)}\,dx','軸力、截面與材料都可以隨位置改變'),(r'\delta=\sum_i\frac{N_iL_i}{A_iE_i}','各段常數時的分段加總')],['有集中軸向負載或截面改變時分段。','壓縮段的變形量取負，不能把各段絕對值直接相加。','靜不定求解順序：平衡、幾何相容、材料關係。'],'最大應力與最大伸長量不一定由同一段控制。','axial')
sec('熱效應',['自由均勻升溫會產生熱伸長，但不一定產生應力。當約束阻止熱變形，才需要機械應變抵消熱應變。','有間隙的構件應先判斷是否接觸，再決定相容方程式；接觸前後是不同的受力狀態。'],[(r'\varepsilon_T=\alpha\Delta T,\quad\delta_T=\alpha\Delta T L','均勻熱膨脹'),(r'\delta_{\mathrm{total}}=\frac{NL}{AE}+\alpha\Delta T L','總變形為機械與熱變形之和'),(r'\sigma=-E\alpha\Delta T','兩端完全固定且均勻升溫的等截面桿')],['升溫且完全限制伸長時，桿內產生壓應力。','混合材料的熱膨脹係數與彈性模數應分別帶入。'],'熱應力公式只適用於相應的約束條件。','thermal')
sec('軸向負載下之應變能',['彈性拉桿在加載過程儲存應變能。線彈性下負載與位移成正比，因此能量為最終力與位移乘積的一半。','若內力或截面隨位置變化，從單位長度的能量積分。'],[(r'U=\frac12P\delta=\frac{P^2L}{2AE}','單一等截面線彈性桿'),(r'U=\int_0^L\frac{N(x)^2}{2A(x)E(x)}\,dx','一般軸向變形能')],['應變能非負，但軸力本身可能為拉或壓。','使用牛頓與毫米時，能量單位為牛頓毫米。'],'突然施加的負載與緩慢施加的負載不具有相同能量歷程。','energy')
sec('維氏圖',['維氏圖以幾何方式表示桁架節點的小位移。先依軸力求每根桿的長度改變，再利用端點相對位移在桿軸上的投影等於該伸長量的條件作圖。','固定節點的位移為零，已知節點的位移可作為下一根桿的作圖基準。'],[(r'(\mathbf u_B-\mathbf u_A)\cdot\mathbf e_{AB}=\delta_{AB}','節點相對位移在桿軸上的投影')],['先求桿力與伸長，再畫位移圖。','以同一比例尺畫所有位移向量。','小位移條件下，垂直桿軸的位移只造成二階長度變化。'],'維氏圖畫的是位移向量，不是把原結構直接等比例放大。','williot')
ex('階梯桿的總伸長','同材質鋼桿受30 kN軸向拉力。第一段長1000 mm、面積300 mm²；第二段長500 mm、面積150 mm²。楊氏模數200000 MPa，求總伸長。',['兩段串聯且中途沒有其他軸向負載，因此內力相同。','逐段計算變形量後相加。'],[(r'\delta_1=\frac{30000(1000)}{300(200000)}=0.5\ \mathrm{mm}',''),(r'\delta_2=\frac{30000(500)}{150(200000)}=0.5\ \mathrm{mm}',''),(r'\delta=1.0\ \mathrm{mm}','')],'總伸長1.0 mm；第二段較短但較細，伸長量仍與第一段相同。')
ex('完全受限的熱應力','等截面鋼桿兩端完全固定，升溫40°C。楊氏模數200 GPa，線膨脹係數每°C為12×10⁻⁶。求熱應力。',['完全固定使總伸長為零。','機械壓縮應變必須抵消自由熱應變。'],[(r'\sigma=-200000(12\times10^{-6})(40)=-96\ \mathrm{MPa}','')],'桿內產生96 MPa壓應力。')

chapter('質心、形心及慣性矩','Centroids and Area Moments','從面積分布求形心、慣性矩與主軸。這些幾何量決定構件抵抗彎曲與扭轉的能力，須與質量慣性矩分清楚。')
sec('重心、形心與質量中心',['重心描述重力合力的作用位置，質量中心由質量分布決定，形心則只與幾何面積或體積分布有關。','均勻重力場中，重心與質量中心重合；均質等厚平板的質量中心也與面積形心重合。'],[(r'\bar x=\frac{\int x\,dm}{\int dm},\quad\bar x_A=\frac{\int x\,dA}{A}','質量中心與面積形心')],['對稱軸上必有形心。','非均質構件須以質量或密度加權，不能只用面積。'],'中空或凹形截面的形心可能位於材料之外。','centroid')
sec('各類重（形）心求法',['組合截面可以拆成矩形、三角形、圓等已知形心的基本圖形。孔洞以負面積處理。','用同一座標原點量每個子面積形心的位置，再作面積的一次矩加總。'],[(r'\bar x=\frac{\sum A_ix_i}{\sum A_i},\quad\bar y=\frac{\sum A_iy_i}{\sum A_i}','挖除區域的面積取負')],['所有距離都應相對同一基準。','用對稱性檢查答案是否合理。'],'幾何線段、薄板面積與立體體積應分別使用長度、面積與體積作權重。','composite')
sec('慣性矩與極慣性矩',['面積慣性矩把面積依離軸距離的平方加權。遠離中性軸的材料對抗彎剛度的貢獻較大。','平行軸定理將形心軸慣性矩轉移到另一條平行軸；極慣性矩是兩條互相垂直面積軸慣性矩之和。'],[(r'I_x=\int_A y^2\,dA,\quad I_y=\int_A x^2\,dA,\quad J_O=I_x+I_y','面積慣性矩單位為長度四次方'),(r'I=I_c+Ad^2','形心軸至平行軸的距離為d'),(r'I_{x,\mathrm{rect}}=\frac{bh^3}{12},\quad J_{\mathrm{circle}}=\frac{\pi d^4}{32}','矩形形心軸與實心圓極慣性矩')],['組合截面先找形心，再逐塊平移及加減。','孔洞的自身慣性矩與平行軸項都必須扣除。'],'面積慣性矩不可與動力學的質量慣性矩混用。','inertia')
sec('截面係數與迴轉半徑',['截面係數把慣性矩與最外纖維距離結合，用於彎曲強度。迴轉半徑把面積分布濃縮為等效離軸距離，用於柱的細長比。','不對稱截面上下緣距中性軸不同，應分別計算兩個截面係數。'],[(r'S=\frac Ic,\quad r_g=\sqrt{\frac IA}','截面係數為長度三次方，迴轉半徑為長度'),(r'\sigma_{\max}=\frac{M}{S}','線彈性純彎曲的最外纖維應力')],['同面積下，增加高度常能大幅提升強軸抗彎能力。','柱常由較小主慣性矩的方向先挫曲。'],'極迴轉半徑與單軸迴轉半徑定義不同。')
sec('轉軸公式',['非對稱截面對一般座標軸可能有非零慣性積。旋轉到主軸後，慣性積為零，對應最大與最小面積慣性矩。','轉軸公式與應力莫爾圓有類似結構，但慣性積的正號定義須先確認。'],[(r'I_{xy}=\int_A xy\,dA','此處慣性積採正積分定義'),(r'I_{x\prime}=\frac{I_x+I_y}{2}+\frac{I_x-I_y}{2}\cos2\theta-I_{xy}\sin2\theta','座標軸逆時針旋轉'),(r'I_{\max,\min}=\frac{I_x+I_y}{2}\pm\sqrt{\left(\frac{I_x-I_y}{2}\right)^2+I_{xy}^2}','主慣性矩')],['轉軸前後兩慣性矩之和不變。','若某軸為截面對稱軸，與其垂直的形心軸組成主軸。'],'旋轉座標軸與把截面本身轉動，在角度正號上不可混淆。','principal')
ex('矩形截面的幾何性質','矩形截面寬60 mm、高120 mm。求水平形心軸的慣性矩、截面係數及迴轉半徑。',['慣性矩中，垂直於所求軸的高度取三次方。','最外緣距水平形心軸60 mm。'],[(r'I_x=\frac{60(120)^3}{12}=8.64\times10^6\ \mathrm{mm^4}',''),(r'S_x=\frac{8.64\times10^6}{60}=144000\ \mathrm{mm^3}',''),(r'r_x=\sqrt{\frac{8.64\times10^6}{60(120)}}=34.64\ \mathrm{mm}','')],'慣性矩8.64×10⁶ mm⁴，截面係數144000 mm³，迴轉半徑34.64 mm。')
ex('偏移軸的慣性矩','面積2000 mm²的截面，形心軸慣性矩為1.2×10⁶ mm⁴。求距離形心軸30 mm的平行軸慣性矩。',['使用平行軸定理，面積乘距離平方必為非負。'],[(r'I=1.2\times10^6+2000(30)^2=3.0\times10^6\ \mathrm{mm^4}','')],'平移後的慣性矩為3.0×10⁶ mm⁴。')

chapter('扭轉負載','Torsion','從圓軸的剪應變與力矩平衡建立扭轉公式，再處理功率、靜不定軸、應變能及薄壁開閉口截面的差異。')
sec('承受扭轉圓桿',['均質等向圓軸在小變形純扭轉下，截面保持平面並繞軸線旋轉。剪應變與到中心的距離成正比，因此外緣剪應力最大。','扭轉角由每段扭轉率沿軸長積分。階梯軸應分段，靜不定軸則須加入兩端或接頭的轉角相容。'],[(r'\tau(r)=\frac{Tr}{J},\quad\tau_{\max}=\frac{Tc}{J}','線彈性圓軸'),(r'\phi=\int_0^L\frac{T(x)}{G(x)J(x)}\,dx','扭轉角以弧度表示'),(r'J=\frac\pi{32}(d_o^4-d_i^4)','圓環截面極慣性矩')],['先畫扭矩圖，再求各段應力與轉角。','不同段的轉角有正負方向，須代數相加。'],'非圓截面通常會翹曲，不能把其面積極慣性矩直接代入圓軸公式。','torsion')
sec('動力與扭轉的關係',['旋轉軸的機械功率等於扭矩乘角速度。轉速使用每分鐘轉數時，須先換成每秒弧度。','以功率設計軸徑時，需同時檢查強度及剛度：應力不可超過容許值，扭轉角也不可過大。'],[(r'\mathcal P=T\omega,\quad\omega=\frac{2\pi n}{60}','轉速n以每分鐘轉數表示'),(r'T=\frac{60\mathcal P}{2\pi n}','功率為瓦、扭矩為牛頓公尺')],['千瓦要先換成瓦。','同功率下，轉速越低，所需扭矩越大。'],'功率與負載力雖常共用字母P，本章以花體P表示功率。','power')
sec('扭轉負載下之應變能',['扭矩緩慢加載時，扭轉應變能為扭矩與相對轉角乘積的一半。','一般變截面軸可由各微段的扭矩平方積分，並用能量導數求轉角。'],[(r'U=\frac{T^2L}{2GJ}=\frac12T\phi','等扭矩、等截面的線彈性圓軸'),(r'U=\int_0^L\frac{T(x)^2}{2GJ}\,dx','分段常數或變量均可使用')],['能量對外加扭矩的偏導數對應其作用方向的轉角。','扭矩使用牛頓毫米時，彈性模數應搭配MPa。'],'能量公式中的扭矩須為截面內扭矩。')
sec('薄壁容器的扭轉',['單室閉口薄壁截面的剪力流沿周界為常數，剪應力則與局部壁厚成反比。','開口薄壁截面的抗扭能力遠小於同尺寸閉口截面，不能沿用閉口的剪力流公式。'],[(r'q=\frac{T}{2A_m},\quad\tau(s)=\frac q{t(s)}','單室閉口薄壁截面；面積取壁厚中線包圍區'),(r'\phi=\frac{TL}{4A_m^2G}\oint\frac{ds}{t(s)}','等截面、單一剪力模數的閉口截面'),(r'J_t\simeq\frac13\sum_i b_it_i^3','狹長矩形片組成的開口薄壁截面近似')],['分清中線包圍面積與材料截面面積。','同一剪力流下，最薄處的剪應力最大。'],'多室截面須加入各室轉角相容，剪力流不再只由單一式子決定。','closed')
ex('實心圓軸的應力與扭轉角','直徑40 mm、長1000 mm的實心圓軸承受500 N·m扭矩，剪力模數80 GPa。求最大剪應力與扭轉角。',['把扭矩換成500000 N·mm。','先求極慣性矩，再分別計算應力與角度。'],[(r'J=\frac{\pi40^4}{32}=251327\ \mathrm{mm^4}',''),(r'\tau_{\max}=\frac{500000(20)}{251327}=39.79\ \mathrm{MPa}',''),(r'\phi=\frac{500000(1000)}{80000(251327)}=0.02487\ \mathrm{rad}=1.425^{\circ}','')],'最大剪應力39.8 MPa，扭轉角約1.425°。')
ex('由功率求扭矩','轉軸以600 rpm傳遞15 kW功率，求扭矩。',['先將轉速換成每秒弧度。','功率除以角速度即為扭矩。'],[(r'\omega=\frac{2\pi(600)}{60}=20\pi\ \mathrm{rad/s}',''),(r'T=\frac{15000}{20\pi}=238.73\ \mathrm{N\,m}','')],'所需扭矩約238.7 N·m。')

chapter('剪力圖與彎矩圖','Shear Force and Bending Moment','先用整體平衡求反力，再用截面法建立剪力與彎矩函數。以負載、剪力與彎矩間的微分及面積關係檢查圖形。')
sec('樑的支承及種類',['簡支樑通常由鉸支承與滾支承支撐；懸臂樑由固定端約束位移與轉角；外伸樑則有跨出支承之外的部分。','先數未知反力，再確認獨立平衡式是否足夠。連續樑與撐桿懸臂樑通常還需要變形條件。'],[],['支承形式決定反力分量，也決定後續撓曲線邊界條件。','內鉸可以傳力，但理想內鉸不傳彎矩。'],'不能只因反力數目等於平衡式數目，就忽略可能存在的不穩定幾何。','supports')
sec('剪力圖及彎矩圖',['本章以向下分布負載為正，正彎矩使樑下緣受拉；相應的剪力正號由微分關係固定。','在各負載改變處分段，以截面法求函數，再連成剪力圖與彎矩圖。圖形的斜率、面積與跳躍量可互相驗證。'],[(r'\frac{dV}{dx}=-w(x),\quad\frac{dM}{dx}=V(x)','向下負載為正、正彎矩為下緣受拉'),(r'V(b)-V(a)=-\int_a^b w(x)\,dx','負載圖面積給剪力變化'),(r'M(b)-M(a)=\int_a^b V(x)\,dx','剪力圖面積給彎矩變化')],['集中力造成剪力圖跳躍；集中力偶造成彎矩圖跳躍。','沒有分布負載的區間，剪力為常數、彎矩為直線。','平滑區段中，剪力為零處是彎矩極值的候選點。'],'最大彎矩也可能位於集中力、集中力偶、端點或分段交界處。','shear')
ex('簡支樑承受均布負載','長4 m簡支樑承受全跨向下均布負載6 kN/m。求反力、剪力與彎矩函數及最大彎矩。',['由對稱性與平衡，兩端反力各為總負載的一半。','從左支承量起，對長度為x的左段取截面。'],[(r'R_A=R_B=\frac{6(4)}2=12\ \mathrm{kN}',''),(r'V(x)=12-6x,\quad M(x)=12x-3x^2','x使用公尺，剪力為千牛頓、彎矩為千牛頓公尺'),(r'V=0\Rightarrow x=2\ \mathrm m,\quad M_{\max}=12\ \mathrm{kN\,m}','')],'剪力圖為斜直線，彎矩圖為拋物線；跨中最大彎矩12 kN·m。')
ex('懸臂樑自由端集中力','長2 m懸臂樑自由端受到5 kN向下力。求固定端反力與最大彎矩大小。',['固定端的向上反力平衡集中力。','固定端反力矩平衡外力對固定端的力矩。'],[(r'R_A=5\ \mathrm{kN},\quad |M_A|=5(2)=10\ \mathrm{kN\,m}','')],'固定端最大彎矩大小10 kN·m；依下緣受拉為正的慣例，樑內彎矩為負。')

chapter('樑的應力','Stresses in Beams','把彎矩與剪力轉為截面上的正向及剪應力，並延伸到複合樑、剪力流與剪力中心。')
sec('樑的彎曲應力',['細長樑在小變形下採平面截面假設：變形前的平面截面仍保持平面。均質線彈性樑的應變與應力沿高度呈線性分布。','純彎曲的中性軸通過截面形心；正彎矩使下緣受拉，上緣受壓。'],[(r'\sigma_x(y)=-\frac{My}{I},\quad\frac1\rho=\frac{M}{EI}','向上y為正、正彎矩使下緣受拉'),(r'|\sigma_{\max}|=\frac{|M|c}{I}=\frac{|M|}{S}','最外纖維應力')],['先由剪力與彎矩圖求危險截面的彎矩。','孔洞與截面突變的局部應力集中需另行考慮。'],'公式假設線彈性、小變形及適用的樑模型。','bending')
sec('複合樑之彎曲應力分析',['不同材料緊密結合時，接觸界面的軸向應變相容，但應力會依楊氏模數不同而改變。','轉換截面法以模數比換算面積，使各材料的抗彎貢獻可在同一參考材料下加總。'],[(r'\bar y=\frac{\sum E_iA_iy_i}{\sum E_iA_i},\quad D=\sum E_iI_i','各段慣性矩均對實際中性軸'),(r'\kappa=\frac{M}{D},\quad\sigma_i=-E_i\kappa(y-\bar y)','完全結合、線彈性複合樑')],['先找模數加權的中性軸。','轉換截面後求得的參考應力，須乘模數比才是另一材料的實際應力。'],'界面滑移或脫離時，完全結合假設不再成立。','compositebeam')
sec('樑的剪應力',['樑內剪應力分布由縱向微段的平衡推導。計算某高度的剪應力時，面積一次矩取該高度一側的部分面積，慣性矩則取整個截面。','矩形截面的剪應力呈拋物線，表面為零、中性軸最大；工字形截面的腹板通常承受大部分剪力。'],[(r'\tau=\frac{VQ}{It},\quad Q=\int_{A^\ast}y\,dA','t是所求高度的局部截面寬度'),(r'\tau_{\max,\mathrm{rect}}=\frac{3V}{2A}','矩形截面中性軸的最大剪應力')],['先畫出用來求一次矩的部分面積。','剪應力與彎曲應力的最大值通常不在同一點。'],'不要把Q誤用成整個截面的面積一次矩；形心軸下全截面一次矩為零。','beamshear')
sec('樑的剪力流及剪力中心',['剪力流是沿薄壁或接合面的每單位長度剪力。接合件須將上下構件的縱向力變化互相傳遞，才能維持共同彎曲。','剪力中心是橫向負載通過時不造成附加扭轉的位置；對開口非對稱截面，它可能位於截面之外。'],[(r'q=\frac{VQ}{I},\quad F_{\mathrm{fastener}}=qs','單列等間距接合件；s為間距')],['將各壁段剪力流的力與力矩合成，以定位剪力中心。','雙對稱截面的剪力中心與形心重合。'],'形心與剪力中心是不同概念，單對稱截面通常只保證剪力中心位於對稱軸上。','flow')
ex('矩形樑的彎曲與剪應力','矩形截面寬60 mm、高120 mm，截面彎矩3 kN·m、剪力10 kN。求最大彎曲應力與最大剪應力。',['慣性矩為8.64×10⁶ mm⁴。','彎曲應力最大值在外緣，剪應力最大值在中性軸。'],[(r'|\sigma_{\max}|=\frac{3\times10^6(60)}{8.64\times10^6}=20.83\ \mathrm{MPa}',''),(r'\tau_{\max}=\frac{3(10000)}{2(60)(120)}=2.083\ \mathrm{MPa}','')],'外緣彎曲應力20.83 MPa，中性軸剪應力2.083 MPa。')
ex('接合件的間距','某樑接合面剪力流為120 N/mm，每個接合件容許剪力6 kN，只有一列接合件。求最大間距。',['一個接合件承受其分攤長度內的剪力流。'],[(r's_{\max}=\frac{F_{\mathrm{allow}}}{q}=\frac{6000}{120}=50\ \mathrm{mm}','')],'接合件間距不得超過50 mm。')

chapter('組合應力及破壞理論','Combined Loading and Failure','在同一截面、同一材料點疊加不同負載造成的應力，再求主應力並選用符合材料破壞模式的強度準則。')
sec('組合應力',['軸力、彎矩、扭矩及剪力可能同時存在。先分別計算各負載在目標點造成的應力，再依方向與正號相加。','不可直接把不同位置的各個最大值拼在一起。求得目標點的應力分量後，才進行主應力與最大剪應力分析。'],[(r'\sigma_x=\frac NA-\frac{M_zy}{I_z}+\frac{M_yz}{I_y}','採主形心軸，且彎矩正號依右手定則'),(r'\tau_{\mathrm{torsion}}=\frac{Tr}{J}','圓軸扭轉剪應力')],['畫出截面與目標點，標示各應力方向。','軸力與彎曲正向應力可代數相加。','扭轉剪應力與樑剪應力須先投影到相同方向。'],'線性疊加需滿足線彈性與小變形等條件。','combined')
sec('破壞理論',['延性材料常以降伏為設計極限，可採最大剪應力理論或畸變能理論；脆性材料則須重視主拉應力及拉壓強度不同的特性。','Tresca準則以最大主應力差控制，von Mises準則以畸變能等效應力控制。安全係數應套用在相同的強度與等效應力比較上。'],[(r'\sigma_{\mathrm{Tresca}}=\max(|\sigma_1-\sigma_2|,|\sigma_2-\sigma_3|,|\sigma_3-\sigma_1|)','最大剪應力降伏準則的等效應力'),(r'\sigma_{\mathrm{VM}}=\sqrt{\frac{(\sigma_1-\sigma_2)^2+(\sigma_2-\sigma_3)^2+(\sigma_3-\sigma_1)^2}{2}}','von Mises等效應力'),(r'\sigma_{\mathrm{VM,plane}}=\sqrt{\sigma_x^2-\sigma_x\sigma_y+\sigma_y^2+3\tau_{xy}^2}','平面應力'),(r'n=\frac{\sigma_Y}{\sigma_{\mathrm{eq}}}','以降伏為基準的安全係數')],['先辨認延性或脆性，再選準則。','主應力排序後，Tresca等效應力就是最大與最小主應力之差。'],'靜水壓應力不產生von Mises等效應力，但不表示所有材料都不會在高壓下破壞。','failure')
sec('不對稱彎矩',['彎矩方向不沿截面主軸時，會同時繞兩個主軸彎曲，中性軸通常不與彎矩方向平行。','若採非主軸，慣性積會使兩個方向耦合。實務上可先求主形心軸，再將彎矩分解，以避免混淆。'],[(r'\sigma_x=-\frac{M_zy}{I_z}+\frac{M_yz}{I_y}','對主形心軸分別計算再相加'),(r'-\frac{M_zy}{I_z}+\frac{M_yz}{I_y}=0','中性軸由正向應力等於零決定')],['先將彎矩投影到主軸。','逐一檢查截面各角點，找出最大拉、壓應力。'],'非主軸不能略去慣性積而直接使用主軸形式的公式。','biaxial')
ex('拉伸與扭轉的等效應力','某圓軸表面承受80 MPa軸向拉應力及30 MPa扭轉剪應力，另一面內正向應力為零。求von Mises等效應力；材料降伏強度250 MPa時，安全係數為何？',['將同一點的平面應力分量代入等效應力公式。','以降伏強度除以等效應力。'],[(r'\sigma_{\mathrm{VM}}=\sqrt{80^2+3(30)^2}=95.39\ \mathrm{MPa}',''),(r'n=\frac{250}{95.39}=2.62','')],'von Mises等效應力95.39 MPa，降伏安全係數約2.62。')
ex('同一點的主應力','沿用80 MPa拉應力與30 MPa剪應力，求主應力及Tresca安全係數。',['先求平面內主應力，再加入零面外主應力。','最大與最小主應力之差就是Tresca等效應力。'],[(r'\sigma_{1,3}=40\pm\sqrt{40^2+30^2}=90,-10\quad(\mathrm{MPa})','面外主應力為零'),(r'\sigma_{\mathrm{Tresca}}=90-(-10)=100\ \mathrm{MPa},\quad n=2.50','')],'三個主應力為90、0、−10 MPa；Tresca安全係數2.50。')

chapter('樑的彎曲變形','Beam Deflection','以彎矩曲率關係求轉角與撓度，並比較直接積分、奇異函數、力矩面積及重疊法；最後以變形相容解靜不定樑。')
sec('積分法：撓曲線方程式',['小斜率條件下，曲率可用撓曲線的二階導數近似。沿長度積分兩次可得轉角與位移，積分常數由支承及連續條件決定。','本章取向上位移為正，正彎矩使下緣受拉，因此曲率與正彎矩同號。'],[(r'EI\frac{d^2v}{dx^2}=M(x),\quad\theta\simeq\frac{dv}{dx}','小撓度Euler–Bernoulli樑'),(r'EI\theta=\int M\,dx+C_1,\quad EI v=\int\!\int M\,dx\,dx+C_1x+C_2','常數彎曲剛度')],['固定端位移與轉角為零。','簡支端位移為零，但轉角不必為零。','分段交界處通常要求位移與轉角連續。'],'大型轉動、短深樑或顯著剪切變形需採更完整的模型。','deflection')
sec('積分法：奇異函數法',['奇異函數將集中力與分段負載寫成同一條式子，積分時不必對每個區段重新列常數。','括號在位置尚未到達負載起點時為零，超過起點後才啟動；實際截斷的均布負載可用起點與終點兩個項表示。'],[(r'\langle x-a\rangle^n=0\quad(x<a)','未到負載位置時關閉'),(r'\langle x-a\rangle^n=(x-a)^n\quad(x\geq a)','非負整數冪的定義'),(r'\int\langle x-a\rangle^n dx=\frac{\langle x-a\rangle^{n+1}}{n+1}','此式適用非負整數冪')],['先用整體平衡求反力。','每個負載項使用正確的起始位置與正號。','分段回代檢查是否符合原本的彎矩圖。'],'集中力偶與分布負載需以各自正確的奇異函數階數表示。')
sec('力矩面積法',['第一定理：兩截面的相對轉角等於它們之間彎矩除以彎曲剛度圖的面積。第二定理：某點相對另一點切線的偏離量，等於該面積對目標點的一次矩。','切線偏離量不是直接的絕對撓度，必須結合幾何與支承條件換算。'],[(r'\theta_B-\theta_A=\int_A^B\frac{M(x)}{EI}\,dx','第一力矩面積定理'),(r't_{B/A}=\int_A^B\frac{M(x)}{EI}(x_B-x)\,dx','第二力矩面積定理；符號依所用位移慣例')],['將彎矩剛度圖拆成容易求面積與形心的幾何圖形。','圖形跨過零軸時須保留面積正負。'],'以目標點取面積力矩，力臂不可量錯端。','momentarea')
sec('重疊原理',['線彈性小變形下，將複雜負載拆成已知基本負載，分別求撓度與轉角後相加。','可利用懸臂、簡支、集中力與均布負載等標準解，但每個子系統須具有相同邊界條件。'],[(r'v(x)=\sum_i v_i(x),\quad\theta(x)=\sum_i\theta_i(x)','線性疊加'),(r'|v_{\max,\mathrm{cantilever}}|=\frac{PL^3}{3EI}','懸臂自由端集中力'),(r'|v_{\max,\mathrm{UDL}}|=\frac{5wL^4}{384EI}','簡支樑全跨均布負載')],['先統一各標準解的座標與正號。','剛度或支承不同的標準解不可直接混加。'],'線性疊加不適用於降伏後的非線性歷程。')
sec('靜不定樑',['當平衡不足以求出所有反力時，可選多餘反力為冗力，暫時解除該約束，再令負載與冗力造成的位移總和滿足原支承條件。','支承沉陷、溫度與裝配誤差都可能出現在相容方程式右側。'],[(r'v_{\mathrm{load}}+fR=\Delta_{\mathrm{support}}','單一冗力的相容方程式')],['解除冗力後的基本系統必須穩定。','先求冗力，再以整體平衡補回其餘反力。','解完後代回位移條件檢查。'],'多個冗力需解一組相容聯立方程式。','redundant')
ex('懸臂樑的端點撓度','長2000 mm懸臂樑承受自由端向下1000 N集中力，楊氏模數200000 MPa，截面慣性矩8×10⁶ mm⁴。求自由端位移與轉角大小。',['採用懸臂自由端集中力標準解。','保持牛頓、毫米、MPa的一致單位。'],[(r'|v_B|=\frac{1000(2000)^3}{3(200000)(8\times10^6)}=1.667\ \mathrm{mm}','位移向下'),(r'|\theta_B|=\frac{1000(2000)^2}{2(200000)(8\times10^6)}=0.00125\ \mathrm{rad}','')],'自由端向下1.667 mm，轉角大小0.00125 rad。')
ex('撐桿懸臂樑的冗力','長L、剛度EI固定的樑，左端固定、右端另有滾支承，承受全跨均布負載w。求右支承反力。',['先解除右支承，使基本系統成為懸臂。','均布負載造成向下位移，右反力造成向上位移；兩者在右端相抵。'],[(r'-\frac{wL^4}{8EI}+\frac{R_BL^3}{3EI}=0','右支承位移為零'),(r'R_B=\frac{3wL}{8}','')],'右反力為總負載的3/8，左端鉛直反力為總負載的5/8。')

chapter('能量法','Energy Methods','以應變能統一處理軸向、扭轉與彎曲變形，用卡式定理求位移及靜不定反力，再分析溫度與衝擊負載。')
sec('彎曲應變能',['樑的微段轉角由彎矩曲率關係決定；將彎矩所做的微小功積分，即得到彎曲應變能。','細長樑常以彎曲能為主，但短樑或剪力變形明顯時，需要保留剪切能。'],[(r'U_b=\int_0^L\frac{M(x)^2}{2EI}\,dx','線彈性彎曲能'),(r'U_s=\int_0^L\frac{V(x)^2}{2k_sGA}\,dx','剪切修正係數定義為有效剪切剛度係數')],['不同內力函數的區段分別積分。','彎曲剛度隨位置變化時，不可當作常數提出。'],'略去剪切能是模型近似，應依構件細長程度判斷。','energy')
sec('各桿件之應變能',['不同變形模式的線彈性應變能可相加。軸向、扭轉與彎曲分別由對應內力的平方除以剛度積分。','求位移時，先確認哪幾種變形對結果有顯著貢獻，再選擇保留項。'],[(r'U=\int\frac{N^2}{2EA}\,dx+\int\frac{T^2}{2GJ}\,dx+\int\frac{M^2}{2EI}\,dx+U_s','線彈性、小變形、適用各構件模型')],['多根桿件的能量須逐根加總。','取平方前仍須正確求出內力對外力的函數關係。'],'能量中的剛度與內力須對應相同變形模式。')
sec('卡式定理',['在線彈性適用條件下，總應變能對某個外力的偏導數，給出該力作用點沿作用方向的位移。對力偶矩求偏導數則得到轉角。','欲求位置沒有實際外力時，可先加一個虛設力，對它求偏導後再令其為零。'],[(r'\delta_P=\frac{\partial U}{\partial P},\quad\theta_C=\frac{\partial U}{\partial C}','卡式第二定理'),(r'\delta_P=\int\frac{M}{EI}\frac{\partial M}{\partial P}\,dx','只計彎曲變形時')],['先把截面內力完整寫成外力與虛設力的函數。','先偏微分，之後才能把虛設力設為零。','靜不定冗力可由能量偏導數等於指定變位求解。'],'有初始應變時須另外處理其位移貢獻，不能只微分機械應變能。','castigliano')
sec('能量法求解溫度效應',['溫度改變提供初始應變。自由熱膨脹的變位不由機械內力能量直接產生，求相容時應將熱變形另外加入。','以單位負載法處理桿系時，可把各桿自由熱伸長投影到目標位移方向。'],[(r'\delta=\sum_i\frac{N_in_iL_i}{A_iE_i}+\sum_i n_i\alpha_i\Delta T_iL_i','桿系單位負載法；n為單位力造成的無量綱軸力')],['先求實際機械負載與單位虛力的桿力。','熱項的正負取決於虛力桿力與熱伸長方向。'],'受約束的熱膨脹可能同時產生機械內力，需與相容一起求解。')
sec('衝擊負載',['衝擊問題應由能量守恆求最大變形。忽略阻尼與損失時，物體位能減少量轉為結構應變能。','突然施加且持續保持的重力負載，在理想線彈性單自由度模型中，可造成靜態伸長兩倍的最大伸長。'],[(r'W(h+\delta)=\frac12k\delta^2','由高度h落下並使彈簧或等效桿件變形'),(r'\delta=\delta_{\mathrm{st}}\left(1+\sqrt{1+\frac{2h}{\delta_{\mathrm{st}}}}\right),\quad\delta_{\mathrm{st}}=\frac Wk','忽略能量損失的最大位移')],['落體重量與結構回復力不是同一個量。','落下高度之外，還要計入接觸後下降的變形量。'],'動態放大倍數為二的結果有特定理想假設，不能套用在任意撞擊。','impact')
ex('用卡式定理求懸臂端位移','長L、固定彎曲剛度EI的懸臂自由端受力P。僅考慮彎曲，推導端點位移。',['從自由端起算距離x，內彎矩大小為Px。','先求能量，再對P偏微分。'],[(r'U=\int_0^L\frac{P^2x^2}{2EI}\,dx=\frac{P^2L^3}{6EI}',''),(r'\delta_P=\frac{\partial U}{\partial P}=\frac{PL^3}{3EI}','')],'與直接積分法的懸臂端點位移相同。')
ex('落下負載的動態放大','某負載緩慢施加時使結構伸長1 mm，若同一負載由結構上方4 mm落下，忽略損失，求最大伸長與最大彈性力倍率。',['以已知靜態伸長代入能量公式。','線彈性下力與位移成正比，因此兩者的放大倍率相同。'],[(r'\delta=1\left(1+\sqrt{1+\frac{2(4)}1}\right)=4\ \mathrm{mm}',''),(r'\frac{F_{\max}}W=\frac\delta{\delta_{\mathrm{st}}}=4','')],'最大伸長4 mm，最大彈性力為負載重量的4倍。')

chapter('非線（彈）性分析','Inelastic Analysis','追蹤構件從初始降伏到塑性擴展的過程，分辨加載與卸載，並求軸向、扭轉及彎曲構件的極限承載能力。')
sec('軸向負載之非線（彈）性分析',['當材料進入塑性區，應力與應變不再維持相同線性關係。應以材料曲線逐點或逐段求應變，再沿長度積分求伸長量。','靜不定桿組在部分桿件降伏後，內力會重新分配；降伏桿不再沿原彈性剛度持續增力。'],[(r'\delta=\int_0^L\varepsilon\bigl(\sigma(x)\bigr)\,dx,\quad\sigma(x)=\frac{N(x)}{A(x)}','以實際材料組成律換算'),(r'P_Y=A\sigma_Y','均勻單軸、等截面完全塑性材料的降伏負載')],['先找最先降伏的構件或截面。','在每一加載階段重建平衡與相容。','卸載初期通常採彈性斜率，並檢查有無反向降伏。'],'塑性歷程具有路徑依賴，不能直接把最終負載代入彈性公式。','plastic')
sec('扭轉負載下之非線（彈）性分析',['圓軸外緣剪應力先達降伏，繼續增載後塑性區向內擴展。彈性核心內剪應力仍隨半徑線性增加，塑性外環則達到剪降伏應力。','完全塑性扭矩由全截面剪應力對軸線的力矩積分得到。'],[(r'T_Y=\frac\pi2\tau_Yc^3,\quad T_P=\frac{2\pi}{3}\tau_Yc^3','實心圓軸、彈性完全塑性'),(r'T=\frac{2\pi}{3}\tau_Yc^3-\frac\pi6\tau_Ya^3','彈性核心半徑a，外半徑c'),(r'\frac{T_P}{T_Y}=\frac43','實心圓軸塑性扭矩倍率')],['先確認材料剪降伏強度。','完全塑性應力分布不再是從中心到外緣的一條直線。'],'以拉伸降伏強度換算剪降伏強度時，Tresca與von Mises會給不同結果。','plastictorsion')
sec('彎矩負載下之非線（彈）性分析',['樑在最外纖維初始降伏後，塑性區由上下緣向中性軸擴展。完全塑性時，拉壓區應力大小達降伏值。','對拉壓降伏強度相同的材料，塑性中性軸將截面分成相等的拉壓面積；一般非對稱截面不一定通過形心。'],[(r'M_Y=\sigma_Y S,\quad M_P=\sigma_Y Z_p','彈性與塑性截面係數'),(r'Z_p=\int_A|y-y_p|\,dA','相對塑性中性軸的一次絕對矩'),(r'S_{\mathrm{rect}}=\frac{bh^2}{6},\quad Z_{p,\mathrm{rect}}=\frac{bh^2}{4},\quad\frac{M_P}{M_Y}=1.5','矩形截面形狀係數')],['先求初始降伏彎矩，再追蹤塑性區。','卸載後殘留應力由最大加載應力減去彈性卸載應力求得。'],'形成一個塑性鉸不必然使靜不定結構立即成為崩塌機構。','plasticbeam')
ex('矩形樑的降伏與塑性彎矩','寬40 mm、高80 mm的矩形截面，降伏強度250 MPa。求初始降伏彎矩與完全塑性彎矩。',['先求彈性與塑性截面係數。','以降伏強度分別乘上兩種截面係數。'],[(r'S=\frac{40(80)^2}{6}=42666.7\ \mathrm{mm^3}',''),(r'Z_p=\frac{40(80)^2}{4}=64000\ \mathrm{mm^3}',''),(r'M_Y=10.667\ \mathrm{kN\,m},\quad M_P=16.0\ \mathrm{kN\,m}','')],'初始降伏10.667 kN·m，完全塑性16.0 kN·m，形狀係數1.5。')
ex('實心圓軸的塑性扭矩','實心圓軸半徑20 mm，剪降伏強度120 MPa。求初始降伏與完全塑性扭矩。',['初始降伏時應力仍為線性分布。','完全塑性時，除中心點外剪應力大小皆達剪降伏強度。'],[(r'T_Y=\frac\pi2(120)(20)^3=1.508\ \mathrm{kN\,m}',''),(r'T_P=\frac{2\pi}{3}(120)(20)^3=2.011\ \mathrm{kN\,m}','')],'初始降伏扭矩1.508 kN·m，完全塑性扭矩2.011 kN·m。')

chapter('柱','Columns and Buckling','細長壓桿可能在材料降伏以前先失去穩定。由平衡與能量判別穩定性，再以有效長度與細長比評估彈性挫曲。')
sec('結構穩定性及臨界負載',['穩定平衡的系統受到小擾動後，有回到原位置的趨勢；不穩定平衡則會偏離。臨界負載標示原直線平衡失去穩定的門檻。','短柱常由材料壓縮強度控制，細長柱則可能由側向挫曲控制。挫曲是整體幾何穩定問題，不能只比較平均壓應力。'],[(r'\frac{d\Pi}{dq}=0','平衡狀態的總位能一階變分為零'),(r'\frac{d^2\Pi}{dq^2}>0','局部嚴格最小值的穩定性判別')],['先辨認可能的側向變形方向。','臨界附近二階項為零時，需進一步檢查高階項或完整穩定問題。'],'實際柱有初始彎曲、偏心與殘留應力，理想公式不可取代完整設計規範。','stability')
sec('彈性柱之尤拉公式',['理想均質、等截面細長柱承受通過形心的軸向壓力，在線彈性小變形的臨界狀態下可得尤拉負載。','支承條件以有效長度係數表示；同一柱應分別檢查兩個主軸方向，使用相應的慣性矩與有效長度。'],[(r'P_{\mathrm{cr}}=\frac{\pi^2EI}{(KL)^2}','尤拉臨界負載'),(r'\lambda=\frac{KL}{r_g},\quad\sigma_{\mathrm{cr}}=\frac{\pi^2E}{\lambda^2}','細長比與臨界平均壓應力'),(r'K_{\mathrm{pin-pin}}=1,\quad K_{\mathrm{fixed-free}}=2','理想鉸鉸與固定自由'),(r'K_{\mathrm{fixed-fixed}}=0.5,\quad K_{\mathrm{fixed-pin}}\simeq0.699','理想固定固定與固定鉸')],['兩軸分別計算臨界負載，取較小者。','若尤拉應力超過比例限，彈性挫曲假設不成立。','縮短有效長度或增加弱軸慣性矩可提高臨界負載。'],'短柱與中等細長柱應採相應的非彈性或規範設計模型。','buckling')
ex('兩端鉸支柱的臨界負載','長3000 mm的兩端鉸支鋼柱，楊氏模數200000 MPa，弱軸慣性矩2×10⁶ mm⁴，面積2000 mm²。求尤拉臨界負載及細長比。',['兩端鉸支的有效長度係數為一。','使用弱軸慣性矩，並求迴轉半徑。'],[(r'r_g=\sqrt{\frac{2\times10^6}{2000}}=31.62\ \mathrm{mm},\quad\lambda=94.87',''),(r'P_{\mathrm{cr}}=\frac{\pi^2(200000)(2\times10^6)}{3000^2}=438.65\ \mathrm{kN}',''),(r'\sigma_{\mathrm{cr}}=219.32\ \mathrm{MPa}','仍須與材料比例限比較')],'理想尤拉負載438.65 kN，細長比94.87；材料須在此應力下仍符合線彈性。')
ex('支承條件對挫曲的影響','同一根柱由兩端鉸支改成一端固定、一端自由，其理想尤拉負載如何改變？',['有效長度係數由一變為二。','尤拉負載與有效長度的平方成反比。'],[(r'\frac{P_{\mathrm{fixed-free}}}{P_{\mathrm{pin-pin}}}=\left(\frac12\right)^2=\frac14','')],'固定自由柱的理想臨界負載只有鉸鉸柱的四分之一。')
